.header-left .company-name {
    font-size: 24pt;
    font-weight: 700;
    color: var(--primary);
    margin: 0;
    letter-spacing: 1px;
}

.header-left .company-tagline {
    font-size: 10pt;
    color: #0389ff;
    margin: 2px 0 0 0;
    letter-spacing: 10px;
    font-weight: bold;
}

.header-right {
    display: table-cell;
    vertical-align: middle;
    text-align: right;
    width: 50%;
}

.invoice-title {
    font-size: 11pt;
    font-weight: 700;
    color: var(--accent);
    letter-spacing: 2px;
    margin: 0;
    text-transform: uppercase;
}

/* NCF block — top right priority */
.ncf-block {
    display: inline-block;
    background: var(--light-bg);
    border-left: 3px solid var(--accent);
    border-right: 3px solid var(--accent);
    border-radius: 6px;
    padding: 6px 10px;
    margin: 6px 0 4px 0;
    text-align: left;
}

.ncf-row {
    font-size: 8.5pt;
    line-height: 1.4;
}

.ncf-label {
    color: var(--text-mid);
    font-weight: 600;
}

.ncf-value {
    color: var(--primary);
    font-weight: 700;
    font-family: 'Courier New', monospace;
    letter-spacing: 0.5px;
}

.invoice-number {
    font-size: 16pt;
    font-weight: 700;
    color: var(--primary);
    margin: 4px 0 0 0;
    letter-spacing: 0.5px;
}

.invoice-meta {
    font-size: 8.5pt;
    color: var(--text-mid);
    margin: 4px 0 8px 0;
}

.status-badge {
    display: inline-block;
    padding: 4px 16px;
    border-radius: 14px;
    font-size: 8.5pt;
    font-weight: 700;
    color: var(--white);
    text-transform: uppercase;
    letter-spacing: 0.8px;
}

.status-draft { background: var(--text-mid); }
.status-unpaid { background: var(--accent); }
.status-paid { background: var(--green); }
.status-overdue { background: var(--yellow); color: var(--text-dark); }
.status-cancelled { background: #555; }

/* INFO BLOCKS */
.info-section {
    display: table;
    width: 100%;
    padding: 0 40px 0 40px;
    box-sizing: border-box;
    table-layout: fixed;
}

.info-block {
    display: table-cell;
    background: var(--light-bg);
    border-radius: 8px;
    padding: 12px 14px;
    vertical-align: top;
    border-top: 3px solid var(--accent);
}

.info-spacer {
    display: table-cell;
    width: 12px;
}

.info-block-title {
    font-size: 8pt;
    font-weight: 700;
    color: var(--primary);
    text-transform: uppercase;
    letter-spacing: 0.8px;
    padding-bottom: 4px;
    border-bottom: 2px solid var(--accent);
    margin-bottom: 8px;
    display: inline-block;
}

.info-row {
    display: table;
    width: 100%;
    padding: 2px 0;
}

.info-label {
    display: table-cell;
    font-size: 8pt;
    color: var(--text-mid);
    width: 38%;
}

.info-value {
    display: table-cell;
    font-size: 8pt;
    font-weight: 700;
    color: #2e6cb5;
    text-align: right;
    word-wrap: break-word;
}

/* SUMMARY CARDS */
.summary-section {
    display: table;
    width: 100%;
    padding: 14px 40px;
    box-sizing: border-box;
    table-layout: fixed;
}

.summary-card {
    display: table-cell;
    text-align: center;
    background: var(--light-bg);
    border-radius: 8px;
    padding: 6px 8px;
    vertical-align: middle;
    border-left: 2px solid var(--accent);
    border-right: 2px solid var(--accent);
}

.summary-card.highlight {
    background: var(--primary);
    border-top: 2px solid var(--accent);
}

.summary-spacer {
    display: table-cell;
    width: 10px;
}

.summary-label {
    font-size: 7pt;
    font-weight: 700;
    color: var(--text-mid);
    text-transform: uppercase;
    letter-spacing: 0.8px;
}

.summary-value {
    font-size: 13pt;
    font-weight: 700;
    color: #2e6cb5;
    margin-top: 3px;
}

.summary-card.highlight .summary-label {
    color: var(--light-accent);
}

.summary-card.highlight .summary-value {
    color: var(--white);
}

/* ITEMS TABLE */
.items-section {
    padding: 0 40px;
}

.items-table-wrapper {
    border-radius: 8px;
    overflow: hidden;
    border: 1px solid var(--border-light);
}

.items-table {
    width: 100%;
    border-collapse: collapse;
}

.items-table thead th {
    background: var(--primary) !important;
    background-color: var(--primary) !important;
    color: var(--white) !important;
    font-size: 7.5pt;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    padding: 10px 10px;
    text-align: left;
    border: none;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

.items-table thead th.right {
    text-align: right;
}

.items-table tbody td {
    font-size: 8.5pt;
    padding: 7px 10px;
    border: none;
    vertical-align: top;
    border-bottom: 1px solid var(--border-light);
}

.items-table tbody td.right {
    text-align: right;
}

.items-table tbody tr:nth-child(even) {
    background: var(--light-bg);
}

.items-table tbody tr:last-child td {
    border-bottom: none;
}

.items-table tbody tr.empty-row td {
    height: 22px;
    border-bottom: 1px solid var(--border-light);
}

/* NOTES */
.notes-section {
    padding: 16px 40px 0 40px;
    margin-top: 12px;
}

.notes-title {
    font-size: 8pt;
    font-weight: 700;
    color: var(--primary);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 4px;
}

.notes-text {
    font-size: 8pt;
    color: var(--text-mid);
    line-height: 1.5;
}

.legal-notice {
    padding: 8px 40px 0 40px;
    font-size: 7.5pt;
    color: var(--text-mid);
    line-height: 1.5;
    font-style: italic;
}

/* BANK INFO */
.bank-section {
    margin: 18px 40px 0 40px;
    background: var(--light-bg);
    border-bottom: 3px solid var(--accent);
    border-radius: 8px;
    padding: 12px 16px;
}

.bank-title {
    font-size: 8pt;
    font-weight: 700;
    color: var(--primary);
    text-transform: uppercase;
    letter-spacing: 0.8px;
    margin-bottom: 8px;
    padding-bottom: 4px;
    border-bottom: 1px solid var(--border-light);
}

.bank-grid {
    display: table;
    width: 100%;
    table-layout: fixed;
}

.bank-item {
    display: table-cell;
    padding: 4px 8px 4px 0;
    vertical-align: middle;
}

.bank-label {
    display: block;
    font-size: 7.5pt;
    color: var(--text-mid);
    text-transform: uppercase;
    letter-spacing: 0.4px;
}

.bank-number {
    display: block;
    font-size: 11pt;
    font-weight: 700;
    color: var(--primary);
    font-family: 'Courier New', monospace;
    letter-spacing: 1.5px;
    margin-top: 3px;
}

/* SIGNATURES + QR */
.signatures-section {
    display: table;
    width: 100%;
    padding: 30px 40px 10px 40px;
    box-sizing: border-box;
    table-layout: fixed;
}

.sig-block {
    display: table-cell;
    width: 33%;
    text-align: center;
    vertical-align: bottom;
    position: relative;
}

.sig-block.sig-qr {
    vertical-align: top;
    padding: 0 8px;
}

.sig-stamp {
    display: block;
    width: 140px;
    opacity: 0.75;
    margin: 0 auto -10px auto;
    position: relative;
    z-index: 2;
}

.sig-line {
    border-top: 1.5px solid var(--text-mid);
    width: 75%;
    margin: 0 auto 6px auto;
    position: relative;
    z-index: 1;
}

.sig-line-empty {
    margin-top: 60px;
}

.sig-label {
    font-size: 7.5pt;
    color: var(--text-mid);
}

.sig-name {
    font-size: 9pt;
    font-weight: 700;
    color: var(--primary);
    margin-top: 2px;
}

.qr-img {
    width: 130px;
    height: 130px;
    display: block;
    margin: 0 auto 6px auto;
}

.qr-info {
    font-size: 7.5pt;
    color: var(--text-dark);
    line-height: 1.4;
}

.qr-info b {
    color: var(--primary);
}

.qr-placeholder {
    width: 130px;
    height: 130px;
    margin: 0 auto;
    border: 1.5px dashed var(--border-light);
    border-radius: 6px;
    display: table;
    background: var(--light-bg);
}

.qr-placeholder small {
    display: table-cell;
    vertical-align: middle;
    text-align: center;
    color: var(--text-mid);
    font-size: 7.5pt;
    padding: 8px;
}

/* FOOTER */
.footer-bar {
    background: var(--primary);
    border-top: 3px solid var(--accent);
    padding: 9px 40px;
    text-align: center;
    font-size: 7pt;
    color: var(--light-accent);
    position: fixed;
    bottom: 0;
    left: 0;
    width: 100%;
    box-sizing: border-box;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

/* PRINT FIXES */
@media print {
    .items-table thead th,
    .footer-bar,
    .summary-card.highlight {
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
        color-adjust: exact;
    }
}
